/* Ngữ pháp A1 · Beginner — sinh tự động bởi tools/build-grammar.py (npm run build:grammar), đừng sửa tay */
(window.FA_GRAMMAR_LESSONS = window.FA_GRAMMAR_LESSONS || {})["A1"] = [{"n":1,"title":"To be & subject pronouns","sections":[{"h":"TRỌNG TÂM","items":[{"p":"To be là động từ nối. Nó gắn chủ ngữ với một danh từ, một tính từ hoặc một trạng ngữ chỉ nơi chốn để giới thiệu, miêu tả hoặc nêu vị trí. Dạng của to be đổi theo chủ ngữ, nên bước đầu tiên luôn là xác định chủ ngữ thuộc ngôi nào và ở số ít hay số nhiều."},{"p":"Cấu trúc chính: S + am/is/are + bổ ngữ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She is a student. (Giới thiệu danh tính, nghề nghiệp | Miêu tả đặc điểm, trạng thái | Nêu vị trí và quê quán)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Giới thiệu danh tính, nghề nghiệp: Sau to be là một cụm danh từ cho biết chủ ngữ là ai, làm gì. (I am a student. / She is my form teacher.)"},{"p":"Miêu tả đặc điểm, trạng thái: Sau to be là tính từ; tiếng Anh không dùng thêm động từ nào khác trước tính từ. (The soup is hot. / We are tired.)"},{"p":"Nêu vị trí và quê quán: Sau to be là trạng ngữ chỉ nơi chốn hoặc cụm be from + địa danh. (The keys are on the table. / Nam is from Hue.)"},{"p":"Nói về tuổi, giờ và thời tiết: Tiếng Anh dùng to be cho tuổi và dùng chủ ngữ hình thức it cho giờ, ngày và thời tiết. (She is twelve. / It is six o'clock.)"},{"p":"Ghi nhớ: Chọn am, is hoặc are theo đại từ nhân xưng hoặc danh từ làm chủ ngữ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + am/is/are + bổ ngữ"},{"table":[["Dạng thức","Công thức / Dạng từ","Ví dụ"],["Khẳng định","I am / you/we/they are / he/she/it is","He is at home."],["Phủ định","S + am/is/are + not","They are not ready."],["Nghi vấn","Am/Is/Are + S + …?","Is she your sister?"],["Dạng rút gọn","I'm / you're / he's / isn't / aren't","I'm not late."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định ngôi và số của chủ ngữ: I đi với am; he, she, it và mọi danh từ số ít đi với is; you cùng tất cả chủ ngữ số nhiều đi với are. (My brother (= he) → is)"},{"p":"02. Đặt to be ngay sau chủ ngữ: To be đứng trước bổ ngữ và không cần thêm trợ động từ nào khác trong câu khẳng định. (The room is clean.)"},{"p":"03. Tạo câu phủ định và câu nghi vấn: To be tự đảm nhiệm vai trò trợ động từ, vì vậy không bao giờ dùng do hoặc does với to be. (Are you busy? — No, I am not.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Giới thiệu","She is a student at Quang Trung School.\n(Cô ấy là học sinh Trường Quang Trung.)","She là ngôi thứ ba số ít nên dùng is; sau is là cụm danh từ làm bổ ngữ."],["Miêu tả","The children are very excited today.\n(Hôm nay các em rất háo hức.)","Children là dạng số nhiều bất quy tắc của child, nên dùng are dù từ này không có đuôi -s."],["Quê quán","My parents are from Da Nang.\n(Bố mẹ tôi là người Đà Nẵng.)","Chủ ngữ số nhiều đi với are; cụm be from + địa danh dùng để nói quê quán."],["Phủ định","I am not hungry yet.\n(Tôi vẫn chưa thấy đói.)","Phủ định chỉ cần thêm not sau am. Dạng rút gọn chuẩn là I'm not - tiếng Anh không có dạng amn't."],["Nghi vấn","Are your friends at the library?\n(Các bạn của bạn có ở thư viện không?)","Are đảo lên trước chủ ngữ your friends, phần còn lại của câu giữ nguyên trật tự."],["Giờ và thời tiết","It is cold and it is almost seven o'clock.\n(Trời lạnh và đã gần bảy giờ.)","It ở đây là chủ ngữ hình thức, không chỉ vật nào cụ thể, dùng cho thời tiết, giờ và ngày tháng."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Dạng to be theo đại từ chủ ngữ"},{"table":[["Đại từ chủ ngữ","Phân loại","Ví dụ"],["I","ngôi thứ nhất số ít","I am here."],["You","ngôi thứ hai, dùng chung cho số ít và số nhiều","You are early."],["He / She / It","ngôi thứ ba số ít","It is new."],["We / They","ngôi thứ nhất và ngôi thứ ba số nhiều","They are outside."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She are a student. → Đã sửa: She is a student. — She thuộc ngôi thứ ba số ít; are chỉ dùng với you và chủ ngữ số nhiều."},{"p":"Chưa đúng: I have twelve years old. → Đã sửa: I am twelve years old. — Tiếng Việt nói “tôi 12 tuổi” theo lối sở hữu, nhưng tiếng Anh dùng to be để nói tuổi."},{"p":"Chưa đúng: Do you are ready? → Đã sửa: Are you ready? — To be đã là trợ động từ, nên câu hỏi tạo bằng cách đảo to be chứ không thêm do."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Chủ ngữ là đại từ nào hoặc là danh từ số ít hay số nhiều."},{"p":"Dạng am, is, are đã khớp với chủ ngữ đó."},{"p":"Câu phủ định có not đặt ngay sau to be."},{"p":"Câu hỏi đảo to be lên trước chủ ngữ và không có do hoặc does."}]}],"id":"a1-01"},{"n":2,"title":"Object pronouns","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mỗi đại từ nhân xưng có hai dạng: dạng chủ ngữ (I, he, we…) và dạng tân ngữ (me, him, us…). Dạng tân ngữ dùng khi đại từ chịu tác động của động từ hoặc đứng sau giới từ. Nhờ đại từ tân ngữ, người viết không phải lặp lại cùng một cụm danh từ trong câu kế tiếp."},{"p":"Cấu trúc chính: V / giới từ + me/you/him/her/it/us/them"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): My teacher helps us. (Làm tân ngữ trực tiếp của động từ | Đứng sau giới từ | Tránh lặp lại danh từ đã nhắc)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Làm tân ngữ trực tiếp của động từ: Đại từ đứng ngay sau động từ, chỉ người hoặc vật chịu tác động. (I know her. / Please open it.)"},{"p":"Đứng sau giới từ: Mọi giới từ đều đòi hỏi dạng tân ngữ ở phía sau, không có ngoại lệ. (This letter is for you. / Come with us.)"},{"p":"Tránh lặp lại danh từ đã nhắc: Khi người đọc đã biết đối tượng, thay cụm danh từ bằng một đại từ tân ngữ. (I met Mai yesterday. I gave her the book.)"},{"p":"Làm tân ngữ gián tiếp: Với các động từ như give, send, show, tân ngữ gián tiếp chỉ người nhận và đứng trước tân ngữ trực tiếp. (She sent me a postcard.)"},{"p":"Ghi nhớ: Dùng me, you, him, her, it, us, them sau động từ hoặc sau giới từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: V / giới từ + me/you/him/her/it/us/them"},{"table":[["Vị trí / Cặp từ","Công thức","Ví dụ"],["Cặp chủ ngữ - tân ngữ","I/me, you/you, he/him, she/her, it/it, we/us, they/them","We saw them; they did not see us."],["Sau động từ","S + V + tân ngữ","The dog follows me."],["Sau giới từ","giới từ + tân ngữ","Sit next to him."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định vai trò của đại từ: Nếu đại từ thực hiện hành động thì dùng dạng chủ ngữ; nếu nhận hành động hoặc đứng sau giới từ thì dùng dạng tân ngữ. (She calls me. (she thực hiện, me nhận))"},{"p":"02. Tìm từ đứng ngay trước đại từ: Trước đại từ là động từ hay giới từ thì vị trí đó bắt buộc dùng dạng tân ngữ. (listen to → listen to me)"},{"p":"03. Kiểm tra số và giống của đối tượng: Một người nam dùng him, một người nữ dùng her, vật hoặc con vật dùng it, nhiều đối tượng dùng them. (my keys → them)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Tân ngữ của động từ","My teacher helps us after every lesson.\n(Thầy giáo giúp chúng tôi sau mỗi buổi học.)","Us là tân ngữ trực tiếp của helps; dùng we ở vị trí này là sai vì we chỉ làm chủ ngữ."],["Sau giới từ","Please listen to me for a moment.\n(Hãy nghe tôi một chút.)","Listen luôn đi với giới từ to và sau giới từ phải là dạng tân ngữ me."],["Tránh lặp danh từ","I cannot find my keys. Have you seen them?\n(Tôi không tìm thấy chìa khoá. Bạn có thấy chúng không?)","Them thay cho my keys ở câu trước nên người đọc không phải nghe lại cả cụm danh từ."],["Tân ngữ gián tiếp","Mum made lunch for Hoa and me.\n(Mẹ nấu cơm trưa cho Hoa và tôi.)","Trong cụm nối bằng and, mỗi thành phần vẫn phải ở dạng tân ngữ: for Hoa and me, không phải for Hoa and I."],["Chỉ con vật, đồ vật","The dog is thirsty. Give it some water.\n(Con chó khát rồi. Cho nó chút nước.)","It dùng cho con vật hoặc đồ vật, và dạng tân ngữ của it trùng với dạng chủ ngữ."],["Hai đại từ trong một câu","She is speaking to Nam and me, so she is speaking to us.\n(Cô ấy đang nói với Nam và tôi, tức là đang nói với chúng tôi.)","Nam and me gộp lại thành us; cả hai cách diễn đạt đều ở dạng tân ngữ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba dạng dễ lẫn của một đại từ"},{"table":[["Dạng từ","Chức năng","Ví dụ"],["she (chủ ngữ)","người thực hiện hành động","She writes well."],["her (tân ngữ)","người nhận hành động hoặc sau giới từ","I wrote to her."],["her / hers (sở hữu)","chỉ quan hệ sở hữu, không phải tân ngữ","This is her pen. / This pen is hers."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: My teacher helps we. → Đã sửa: My teacher helps us. — We chỉ đứng ở vị trí chủ ngữ; sau động từ phải dùng us."},{"p":"Chưa đúng: This gift is for she. → Đã sửa: This gift is for her. — Sau giới từ for bắt buộc dùng dạng tân ngữ her."},{"p":"Chưa đúng: Lan gave the tickets to I. → Đã sửa: Lan gave the tickets to me. — Lỗi thường gặp khi người học cho rằng I luôn trang trọng hơn me, nhưng sau giới từ to chỉ có me là đúng."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Đại từ đang nhận hành động hoặc đứng sau giới từ."},{"p":"Đã dùng dạng tân ngữ chứ không phải dạng chủ ngữ."},{"p":"Đại từ khớp số và giống với đối tượng được thay thế."},{"p":"Trong cụm nối bằng and, mọi thành phần đều ở dạng tân ngữ."}]}],"id":"a1-02"},{"n":3,"title":"Nouns & plurals","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Danh từ đếm được trong tiếng Anh phải đổi hình thức khi chỉ nhiều hơn một. Phần lớn danh từ chỉ cần thêm -s, nhưng quy tắc chính tả thay đổi theo âm cuối của từ và một nhóm danh từ quen dùng có dạng số nhiều bất quy tắc cần học thuộc."},{"p":"Cấu trúc chính: book → books | box → boxes | child → children"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): There are three children outside. (Chỉ số lượng nhiều hơn một | Nói về cả loại, cả nhóm | Quyết định dạng động từ theo sau)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Chỉ số lượng nhiều hơn một: Danh từ đếm được bắt buộc mang dấu hiệu số nhiều, không thể để nguyên như tiếng Việt. (I have two sisters.)"},{"p":"Nói về cả loại, cả nhóm: Danh từ số nhiều không có mạo từ dùng để nói về sự vật nói chung. (Dogs are loyal animals.)"},{"p":"Quyết định dạng động từ theo sau: Chủ ngữ số nhiều kéo theo động từ số nhiều, nên nhận diện số của danh từ là bước bắt buộc. (The boxes are heavy.)"},{"p":"Ghi nhớ: Tạo số nhiều bằng -s, -es và nhớ các danh từ số nhiều bất quy tắc."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: book → books | box → boxes | child → children"},{"table":[["Quy tắc","Điều kiện áp dụng","Ví dụ"],["Thêm -s","phần lớn danh từ","book → books, table → tables"],["Thêm -es","sau -s, -ss, -sh, -ch, -x, -z","bus → buses, watch → watches, box → boxes"],["Phụ âm + y → -ies","city → cities, nhưng boy → boys","baby → babies"],["Bất quy tắc","đổi nguyên âm hoặc đổi cả từ","man → men, woman → women, child → children, person → people, foot → feet, tooth → teeth, mouse → mice"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định danh từ có đếm được hay không: Chỉ danh từ đếm được mới có dạng số nhiều; water hay information thì không. (chair → chairs, nhưng water giữ nguyên)"},{"p":"02. Xem âm và chữ cuối của từ: Các từ kết thúc bằng âm xuýt cần thêm -es để phát âm được; phụ âm + y đổi y thành i rồi thêm -es. (dish → dishes / story → stories)"},{"p":"03. Kiểm tra nhóm bất quy tắc: Những danh từ chỉ người và bộ phận cơ thể thường bất quy tắc, phải nhớ theo cặp. (one tooth — two teeth)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Số nhiều đều","She bought two notebooks and three pens.\n(Cô ấy mua hai quyển vở và ba cái bút.)","Sau số từ lớn hơn một, danh từ đếm được bắt buộc ở dạng số nhiều."],["Thêm -es","The buses stop in front of two churches.\n(Xe buýt dừng trước hai nhà thờ.)","Bus kết thúc bằng -s và church kết thúc bằng -ch, cả hai đều thêm -es."],["Phụ âm + y","Both cities have large libraries.\n(Cả hai thành phố đều có thư viện lớn.)","City và library kết thúc bằng phụ âm + y nên đổi y thành i rồi thêm -es."],["Bất quy tắc chỉ người","There are three children outside and two women in the hall.\n(Có ba đứa trẻ ở ngoài và hai người phụ nữ trong hội trường.)","Child → children và woman → women là dạng bất quy tắc, không thêm -s."],["Người nói chung","Many people walk to work in this district.\n(Nhiều người đi bộ đến chỗ làm ở khu này.)","People là dạng số nhiều của person và luôn đi với động từ số nhiều."],["Danh từ không đổi dạng","We saw two sheep and several fish in the pond.\n(Chúng tôi thấy hai con cừu và vài con cá trong ao.)","Sheep và fish giữ nguyên hình thức ở số nhiều; số lượng được thể hiện qua số từ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cách tạo số nhiều thường bị lẫn"},{"table":[["Cách tạo","Đặc điểm","Ví dụ"],["-s thuần","âm cuối dễ phát âm","cat → cats"],["-es","âm cuối là âm xuýt, cần thêm nguyên âm","box → boxes"],["-ies","phụ âm + y","party → parties"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: There are three childs outside. → Đã sửa: There are three children outside. — Child thuộc nhóm bất quy tắc nên không thêm -s."},{"p":"Chưa đúng: I need two box. → Đã sửa: I need two boxes. — Sau số từ lớn hơn một, danh từ đếm được không được giữ dạng số ít."},{"p":"Chưa đúng: Many peoples came. → Đã sửa: Many people came. — People vốn đã là số nhiều; peoples chỉ dùng khi nói về nhiều dân tộc khác nhau."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Danh từ này có đếm được hay không."},{"p":"Dạng số nhiều đúng quy tắc chính tả theo âm cuối."},{"p":"Từ có thuộc nhóm bất quy tắc cần nhớ hay không."},{"p":"Động từ trong câu đã hòa hợp với số của danh từ."}]}],"id":"a1-03"},{"n":4,"title":"Countable & uncountable nouns","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tiếng Anh chia danh từ thành hai loại: đếm được (có số ít, số nhiều, đi với a/an và số từ) và không đếm được (chỉ chất liệu, chất lỏng, khái niệm trừu tượng, luôn ở dạng số ít). Nhiều danh từ tiếng Việt đếm được bình thường lại không đếm được trong tiếng Anh, vì vậy cần nhớ theo danh sách."},{"p":"Cấu trúc chính: a chair | two chairs | some water"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): We need some information. (Chọn mạo từ và lượng từ đúng | Chia động từ cho đúng | Đếm danh từ không đếm được bằng đơn vị)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Chọn mạo từ và lượng từ đúng: Danh từ đếm được số ít cần a/an; danh từ không đếm được đi với some, any, much, a little. (a chair / some advice)"},{"p":"Chia động từ cho đúng: Danh từ không đếm được luôn đi với động từ số ít dù mang nghĩa khối lượng lớn. (The news is good.)"},{"p":"Đếm danh từ không đếm được bằng đơn vị: Muốn chỉ số lượng, thêm một danh từ chỉ đơn vị ở trước. (two glasses of water / a piece of advice)"},{"p":"Ghi nhớ: Danh từ không đếm được không đi với a/an và không có dạng số nhiều."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: a chair | two chairs | some water"},{"table":[["Loại danh từ","Công thức","Ví dụ"],["Đếm được","a/an + số ít | số từ + số nhiều","a book, three books"],["Không đếm được","some/any/much + danh từ số ít","some water, much time"],["Đơn vị đo","a piece/slice/bottle/kilo of + danh từ không đếm được","a piece of furniture"],["few / a few","few + danh từ số nhiều = ít tới mức gần như không | a few = một vài (đủ dùng)","Few researchers agree. / A few samples remain."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Thử đếm danh từ bằng số từ: Nếu không nói được two informations thì đó là danh từ không đếm được. (two advices → sai)"},{"p":"02. Bỏ mạo từ và đuôi -s: Thay vào đó dùng some trong câu khẳng định hoặc any trong câu phủ định và nghi vấn. (We need some information.)"},{"p":"03. Thêm danh từ đơn vị khi cần đếm: Danh từ đơn vị mới là phần mang dấu hiệu số nhiều, danh từ chính giữ nguyên. (three pieces of luggage)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Không đếm được","We need some information about the course.\n(Chúng tôi cần một ít thông tin về khoá học.)","Information không đếm được nên không dùng an information và không có dạng informations."],["Lời khuyên","She gave me two pieces of advice.\n(Cô ấy cho tôi hai lời khuyên.)","Advice không đếm được; muốn đếm thì dùng đơn vị piece và chính piece mới mang -s."],["Đồ đạc","There is not much furniture in the room.\n(Trong phòng không có nhiều đồ đạc.)","Furniture không đếm được nên đi với much và động từ số ít is."],["Đếm được","I bought three chairs and a table.\n(Tôi mua ba cái ghế và một cái bàn.)","Chair và table đếm được nên có dạng số nhiều và đi được với a."],["Danh từ chỉ môn học, tin tức","The news is good and physics is my favourite subject.\n(Tin tức tốt lành và vật lí là môn tôi thích nhất.)","News và physics có đuôi -s nhưng không đếm được, nên vẫn dùng động từ số ít."],["Cùng một từ, hai cách dùng","Would you like some coffee? — Yes, two coffees, please.\n(Bạn uống chút cà phê nhé? — Vâng, cho hai cốc cà phê.)","Coffee là chất lỏng nên không đếm được, nhưng khi nói về suất phục vụ thì được dùng như danh từ đếm được."],["Động từ theo sau","Local knowledge of tidal patterns was more reliable than the model.\n(Hiểu biết bản địa về thuỷ triều đáng tin hơn mô hình.)","Knowledge không đếm được nên động từ ở số ít: was, không phải were - dù câu có chữ patterns số nhiều đứng giữa."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Danh từ không đếm được thường bị dùng sai"},{"table":[["Danh từ","Nghĩa","Ví dụ"],["information","thông tin","a piece of information"],["advice","lời khuyên","some useful advice"],["furniture","đồ đạc, nội thất","a lot of furniture"],["luggage / equipment /homework / knowledge","hành lí, thiết bị, bài tập về nhà, kiến thức","two items of luggage"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: We need an information. → Đã sửa: We need some information. — Danh từ không đếm được không nhận mạo từ không xác định a/an."},{"p":"Chưa đúng: He gave me many advices. → Đã sửa: He gave me a lot of advice. — Advice không đếm được nên không thêm -s và không đi với many."},{"p":"Chưa đúng: My homeworks are difficult. → Đã sửa: My homework is difficult. — Homework luôn ở dạng số ít và đi với động từ số ít."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Danh từ này có nói được two… hay không."},{"p":"Không có a/an và không có -s nếu danh từ không đếm được."},{"p":"Lượng từ đi kèm đúng loại danh từ."},{"p":"Động từ số ít với danh từ không đếm được."},{"p":"Chủ ngữ không đếm được luôn đi với động từ số ít: knowledge is/was, information has."}]}],"id":"a1-04"},{"n":5,"title":"Possessives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tiếng Anh có ba cách thể hiện quan hệ sở hữu. Tính từ sở hữu (my, your, his…) luôn đứng trước danh từ, còn đại từ sở hữu (mine, yours, his…) thay cho cả cụm “tính từ sở hữu + danh từ” nên đứng một mình. Cách thứ ba là sở hữu cách ’s, dùng khi người sở hữu được gọi bằng tên hoặc danh từ chỉ người."},{"p":"Cấu trúc chính: my book | mine | Lan's book"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): This bag is mine. (Xác định vật thuộc về ai | Tránh lặp danh từ ở câu trả lời | Sở hữu của người và tổ chức)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Xác định vật thuộc về ai: Tính từ sở hữu đứng ngay trước danh từ và không bao giờ đi cùng mạo từ. (my book / her idea)"},{"p":"Tránh lặp danh từ ở câu trả lời: Đại từ sở hữu gói gọn cả cụm danh từ, thường xuất hiện sau động từ to be. (Whose pen is this? — It's mine.)"},{"p":"Sở hữu của người và tổ chức: Thêm ’s vào danh từ chỉ người; danh từ số nhiều có -s thì chỉ thêm dấu nháy. (Lan's bike / the students' project)"},{"p":"Sở hữu của vật: Với vật vô tri, tiếng Anh thường dùng cấu trúc of thay cho ’s. (the roof of the house)"},{"p":"Ghi nhớ: Tính từ sở hữu đứng trước danh từ, đại từ sở hữu đứng một mình, ’s chỉ người sở hữu."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: my book | mine | Lan's book"},{"table":[["Loại sở hữu","Danh sách từ / Công thức","Ví dụ"],["Tính từ sở hữu","my, your, his, her, its, our, their + danh từ","their classroom"],["Đại từ sở hữu","mine, yours, his, hers, ours, theirs (đứng một mình)","That seat is ours."],["Sở hữu cách ’s","danh từ số ít + ’s | danh từ số nhiều có -s + ’","the teacher's desk, the girls' room"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét thành phần đứng sau: Còn danh từ ở sau thì dùng tính từ sở hữu; không còn danh từ nào thì dùng đại từ sở hữu. (my bag ↔ This bag is mine.)"},{"p":"02. Không dùng mạo từ cùng tính từ sở hữu: Tính từ sở hữu đã đủ sức xác định danh từ, nên không viết the my book. (my book, không phải the my book)"},{"p":"03. Đặt dấu nháy theo số của danh từ: Danh từ số ít thêm ’s; danh từ số nhiều đã có -s thì chỉ thêm dấu nháy phía sau. (my brother's room / my brothers' room)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Đại từ sở hữu","This bag is mine, and that one is hers.\n(Cái túi này của tôi, còn cái kia của cô ấy.)","Mine và hers đứng một mình, thay cho my bag và her bag."],["Tính từ sở hữu","Our team finished its report yesterday.\n(Nhóm chúng tôi hoàn thành báo cáo hôm qua.)","Our và its đứng trước danh từ. Its là tính từ sở hữu, khác hẳn it's (= it is)."],["Sở hữu cách số ít","This is Nam's bicycle.\n(Đây là xe đạp của Nam.)","Người sở hữu là một người nên thêm ’s ngay sau tên."],["Sở hữu cách số nhiều","The students' projects are on display.\n(Các dự án của học sinh đang được trưng bày.)","Students đã có -s nên chỉ thêm dấu nháy, không viết students's."],["Sở hữu của vật","The title of the book is very long.\n(Tiêu đề của quyển sách rất dài.)","Với vật vô tri, cấu trúc of tự nhiên hơn the book's title."],["Câu hỏi với whose","Whose keys are these? — They're ours.\n(Đây là chìa khoá của ai? — Của chúng tôi.)","Whose hỏi về người sở hữu; câu trả lời ngắn dùng đại từ sở hữu."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba dạng đi cùng một người sở hữu"},{"table":[["Dạng từ","Chức năng","Ví dụ"],["her + danh từ","tính từ sở hữu","her notebook"],["hers","đại từ sở hữu, đứng một mình","The notebook is hers."],["her (tân ngữ)","không chỉ sở hữu","I called her."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: This is mine bag. → Đã sửa: This is my bag. — Trước danh từ phải dùng tính từ sở hữu my; mine chỉ đứng một mình."},{"p":"Chưa đúng: The dog wagged it's tail. → Đã sửa: The dog wagged its tail. — Its là tính từ sở hữu, còn it's là dạng rút gọn của it is."},{"p":"Chưa đúng: That pen is her. → Đã sửa: That pen is hers. — Sau to be và không có danh từ theo sau thì cần đại từ sở hữu hers."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Sau vị trí sở hữu còn danh từ hay không."},{"p":"Không có mạo từ đứng cùng tính từ sở hữu."},{"p":"Dấu nháy đặt đúng theo số của danh từ chỉ người sở hữu."},{"p":"Its và it's không bị dùng lẫn."}]}],"id":"a1-05"},{"n":6,"title":"This, that, these, those","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Từ chỉ định giúp người nói trỏ đến một đối tượng cụ thể. Việc chọn từ nào phụ thuộc vào hai tiêu chí cùng lúc: khoảng cách (gần người nói dùng this/these, xa dùng that/those) và số lượng (số ít dùng this/that, số nhiều dùng these/those)."},{"p":"Cấu trúc chính: this/that + danh từ số ít | these/those + danh từ số nhiều"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Those books are new. (Trỏ vào vật trước mặt | Làm từ hạn định trước danh từ | Đứng một mình như đại từ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Trỏ vào vật trước mặt: This và these dùng cho vật trong tầm tay, that và those cho vật ở xa hơn. (This seat is free. / Those trees are tall.)"},{"p":"Làm từ hạn định trước danh từ: Từ chỉ định thay chỗ của mạo từ, nên không viết this the book. (I like this song.)"},{"p":"Đứng một mình như đại từ: Khi đối tượng đã rõ, từ chỉ định tự làm chủ ngữ hoặc tân ngữ. (These are my notes.)"},{"p":"Trỏ về thời gian và nội dung vừa nói: This có thể chỉ khoảng thời gian hiện tại; that có thể chỉ sự việc vừa xảy ra hoặc vừa được nhắc. (This week is busy. / That was a good idea.)"},{"p":"Ghi nhớ: Chọn từ chỉ định theo khoảng cách gần hay xa và theo số ít hay số nhiều."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: this/that + danh từ số ít | these/those + danh từ số nhiều"},{"table":[["Phân loại","Công thức","Ví dụ"],["Gần, số ít","this + danh từ số ít","this pen"],["Gần, số nhiều","these + danh từ số nhiều","these pens"],["Xa, số ít","that + danh từ số ít","that building"],["Xa, số nhiều","those + danh từ số nhiều","those buildings"],["Hoà hợp động từ","this/that + danh từ số ít + is/was | these/those + danh từ số nhiều + are/were","Those photos were taken in Hoi An."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định đối tượng ở gần hay ở xa: Gần về không gian hoặc thời gian thì chọn nhóm this/these; xa thì chọn nhóm that/those. (vật trong tay → this)"},{"p":"02. Xác định đối tượng số ít hay số nhiều: Số của từ chỉ định phải khớp với số của danh từ và với động từ theo sau. (these books are…)"},{"p":"03. Kiểm tra sự hòa hợp với động từ: This/that đi với is, these/those đi với are. (That is new. / Those are new.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Xa, số nhiều","Those books on the top shelf are new.\n(Mấy quyển sách trên kệ cao kia là sách mới.)","Books số nhiều và ở xa nên dùng those, kéo theo động từ are."],["Gần, số nhiều","These apples here are fresh.\n(Mấy quả táo ở đây tươi lắm.)","Apples số nhiều và trong tầm tay nên dùng these."],["Gần, số ít","This is my new bag.\n(Đây là cái túi mới của tôi.)","This đứng một mình như đại từ làm chủ ngữ, đi với is."],["Xa, số ít","That house at the end of the street belongs to my uncle.\n(Căn nhà ở cuối phố kia là của chú tôi.)","House số ít và ở xa nên dùng that."],["Giới thiệu qua điện thoại","Hello, this is Mai speaking. Is that Mr Nam?\n(Xin chào, Mai đây. Có phải anh Nam không ạ?)","Khi gọi điện, this chỉ người nói còn that chỉ người ở đầu dây bên kia."],["Trỏ về điều vừa nói","The train was late again. That happens every Monday.\n(Tàu lại trễ. Chuyện đó xảy ra mỗi thứ Hai.)","That trỏ về sự việc vừa được nêu ở câu trước."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai tiêu chí chọn từ chỉ định"},{"table":[["Tiêu chí","Từ chỉ định","Ví dụ"],["Gần + số ít","this","This chair is comfortable."],["Gần + số nhiều","these","These chairs are comfortable."],["Xa + số ít","that","That chair looks old."],["Xa + số nhiều","those","Those chairs look old."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Those book is new. → Đã sửa: Those books are new. — Those đòi hỏi danh từ số nhiều và động từ số nhiều."},{"p":"Chưa đúng: This the pen is mine. → Đã sửa: This pen is mine. — Từ chỉ định đã giữ vai trò hạn định nên không dùng kèm mạo từ the."},{"p":"Chưa đúng: These is my friend. → Đã sửa: This is my friend. — Một người thì dùng this; these chỉ dùng cho số nhiều."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Đối tượng ở gần hay ở xa người nói."},{"p":"Danh từ theo sau ở số ít hay số nhiều."},{"p":"Động từ đã hòa hợp với từ chỉ định."},{"p":"Không có mạo từ đứng kèm từ chỉ định."},{"p":"Chỉ định kéo theo động từ hoà hợp: these/those + danh từ số nhiều đi với are/were."}]}],"id":"a1-06"},{"n":7,"title":"A, an & the","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mạo từ không xác định a/an giới thiệu một đối tượng mới, chưa rõ cụ thể là cái nào. Mạo từ xác định the dùng khi người nghe đã biết chính xác đối tượng nào đang được nói tới, vì nó đã được nhắc trước, vì chỉ có một hoặc vì ngữ cảnh đã làm rõ. Chọn a hay an phụ thuộc vào âm đầu của từ liền sau, không phụ thuộc vào chữ cái."},{"p":"Cấu trúc chính: a + từ có âm đầu là phụ âm | an + từ có âm đầu là nguyên âm | the + danh từ đã xác định"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I saw a dog. The dog was friendly. (Giới thiệu đối tượng lần đầu | Nhắc lại đối tượng đã nêu | Đối tượng duy nhất hoặc đã rõ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Giới thiệu đối tượng lần đầu: A/an đi với danh từ đếm được số ít mà người nghe chưa biết. (I bought a book yesterday.)"},{"p":"Nhắc lại đối tượng đã nêu: Lần thứ hai trở đi, đối tượng đã xác định nên chuyển sang the. (The book is about Hue.)"},{"p":"Đối tượng duy nhất hoặc đã rõ: The dùng khi chỉ có một đối tượng như vậy hoặc người nghe biết ngay là cái nào. (the sun / Close the door, please.)"},{"p":"Nói về nghề nghiệp: Sau to be, nghề nghiệp của một người luôn cần a/an. (She is an engineer.)"},{"p":"Ghi nhớ: Dùng a/an khi nhắc lần đầu, the khi đối tượng đã xác định với cả người nói và người nghe."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: a + từ có âm đầu là phụ âm | an + từ có âm đầu là nguyên âm | the + danh từ đã xác định"},{"table":[["Mạo từ","Quy tắc dùng","Ví dụ"],["a","trước từ có âm đầu là phụ âm","a book, a university, a one-way street"],["an","trước từ có âm đầu là nguyên âm","an apple, an hour, an MBA"],["the","danh từ đã xác định, số ít hoặc số nhiều, đếm được hoặc không","the students, the water in this glass"],["không mạo từ","danh từ số nhiều hoặc không đếm được mang nghĩa chung","Dogs are loyal. Water is essential."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét mức xác định với người nghe: Chưa biết thì dùng a/an, đã biết thì dùng the. (a taxi → the taxi)"},{"p":"02. Nghe âm đầu của từ ngay sau mạo từ: Chọn an khi từ sau có âm đầu là nguyên âm, kể cả khi chữ đầu là phụ âm như hour. (an hour, nhưng a university)"},{"p":"03. Kiểm tra trường hợp không cần mạo từ: Danh từ số nhiều và danh từ không đếm được mang nghĩa khái quát thì không dùng mạo từ. (I like music.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Lần đầu và lần sau","I saw a dog in the garden. The dog was friendly.\n(Tôi thấy một con chó trong vườn. Con chó đó rất thân thiện.)","Lần đầu dùng a vì người nghe chưa biết con nào; lần sau dùng the vì đối tượng đã xác định."],["Âm đầu quyết định","He waited for an hour outside a university.\n(Anh ấy đợi một tiếng bên ngoài một trường đại học.)","Hour có âm đầu là nguyên âm nên dùng an; university có âm đầu /j/ nên dùng a."],["Nghề nghiệp","My aunt is an engineer and my uncle is a teacher.\n(Dì tôi là kĩ sư, còn chú tôi là giáo viên.)","Nghề nghiệp của một người luôn đi với a/an, khác với tiếng Việt."],["Đối tượng duy nhất","The sun rises in the east.\n(Mặt trời mọc ở phía đông.)","Sun và east là những đối tượng duy nhất nên luôn dùng the."],["Nghĩa khái quát","Children need sleep and fresh air.\n(Trẻ em cần ngủ và cần không khí trong lành.)","Danh từ số nhiều và danh từ không đếm được mang nghĩa chung thì không có mạo từ."],["Ngữ cảnh đã rõ","Could you turn off the light, please?\n(Bạn tắt đèn giúp tôi nhé?)","Cả hai người đều biết là cái đèn nào trong phòng nên dùng the ngay lần đầu nhắc."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Những trường hợp a và an dễ chọn sai"},{"table":[["Cụm từ","Lý do","Ví dụ thêm"],["a university / a European city","chữ nguyên âm nhưng đọc thành âm /j/","a useful tool"],["an hour / an honest man","chữ h câm, âm đầu là nguyên âm","an honour"],["an MBA / an X-ray","chữ viết tắt đọc theo tên chữ cái, âm đầu là nguyên âm","an MP3 file"],["a one-way street","one đọc là /wʌn/, âm đầu là phụ âm","a one-day trip"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I saw an university. → Đã sửa: I saw a university. — University tuy bắt đầu bằng chữ u nhưng có âm đầu /j/, một phụ âm."},{"p":"Chưa đúng: She is engineer. → Đã sửa: She is an engineer. — Nghề nghiệp số ít sau to be bắt buộc có mạo từ."},{"p":"Chưa đúng: The life is beautiful. → Đã sửa: Life is beautiful. — Danh từ không đếm được mang nghĩa khái quát thì không dùng the."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Người nghe đã biết đối tượng này chưa."},{"p":"Âm đầu của từ liền sau là nguyên âm hay phụ âm."},{"p":"Danh từ có cần mạo từ hay thuộc trường hợp để trống."},{"p":"Nghề nghiệp số ít đã có a/an."}]}],"id":"a1-07"},{"n":8,"title":"Some, any, much & many","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Lượng từ cho biết số lượng một cách tương đối. Việc chọn lượng từ nào phụ thuộc hai yếu tố: loại danh từ (đếm được hay không đếm được) và loại câu (khẳng định, phủ định hay nghi vấn). Nắm hai trục này là đủ để chọn đúng trong hầu hết tình huống."},{"p":"Cấu trúc chính: many + danh từ đếm được số nhiều | much + danh từ không đếm được"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Do you have any questions? (Lượng không xác định trong câu khẳng định | Phủ định và đặt câu hỏi | Hỏi và phủ định về số lượng lớn)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Lượng không xác định trong câu khẳng định: Some đi với cả danh từ đếm được số nhiều và danh từ không đếm được. (There are some chairs. / I need some help.)"},{"p":"Phủ định và đặt câu hỏi: Any thay chỗ của some trong câu phủ định và câu nghi vấn. (I do not have any money. / Are there any seats?)"},{"p":"Hỏi và phủ định về số lượng lớn: Many dùng với danh từ đếm được, much dùng với danh từ không đếm được. (How many books? / How much water?)"},{"p":"Mời hoặc đề nghị: Some vẫn dùng trong câu hỏi khi người nói mời hoặc đề nghị điều gì. (Would you like some tea?)"},{"p":"Phủ định bằng no và bao quát bằng every: No + danh từ nghĩa là không có chút nào, thay được cho not any khi động từ giữ dạng khẳng định. Every + danh từ số ít nghĩa là tất cả, xét từng cá thể một. (The trial found no significant difference. / Every participant signed a consent form.)"},{"p":"Ghi nhớ: Some dùng trong câu khẳng định, any trong câu phủ định và nghi vấn; much đi với danh từ không đếm được, many với danh từ đếm được."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: many + danh từ đếm được số nhiều | much + danh từ không đếm được"},{"table":[["Loại câu / Lượng từ","Công thức","Ví dụ"],["Khẳng định","some + danh từ số nhiều / không đếm được","We bought some fruit."],["Phủ định","not … any | not much | not many","There isn't any sugar left."],["Nghi vấn","any | how much | how many","How many brothers do you have?"],["Lời mời","Would you like some …?","Would you like some water?"],["no / every / a·an","no + danh từ (động từ khẳng định) | every + danh từ số ít | a/an + danh từ đếm được số ít","There is no evidence. / Every answer counts. / an explanation"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định loại danh từ: Đếm được số nhiều thì đi với many, a few; không đếm được thì đi với much, a little. (many students / much time)"},{"p":"02. Xác định loại câu: Câu khẳng định thường dùng some; câu phủ định và nghi vấn thường dùng any. (some milk → any milk)"},{"p":"03. Kiểm tra ngoại lệ với lời mời: Câu hỏi mang nghĩa mời hoặc xin thì vẫn dùng some. (Can I have some water?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nghi vấn","Do you have any questions about the homework?\n(Bạn có câu hỏi nào về bài tập không?)","Câu nghi vấn dùng any; questions ở số nhiều vì any đi với danh từ đếm được số nhiều."],["Khẳng định","There are some new books in the library.\n(Trong thư viện có mấy quyển sách mới.)","Some trong câu khẳng định chỉ một lượng không cần xác định chính xác."],["Phủ định","We do not have any time left.\n(Chúng ta không còn thời gian nữa.)","Câu phủ định dùng any; time là danh từ không đếm được nên giữ dạng số ít."],["Hỏi số lượng đếm được","How many students are there in your class?\n(Lớp bạn có bao nhiêu học sinh?)","How many đi với danh từ đếm được số nhiều và động từ số nhiều."],["Hỏi số lượng không đếm được","How much sugar do you take in your coffee?\n(Bạn cho bao nhiêu đường vào cà phê?)","Sugar không đếm được nên dùng how much."],["Lời mời","Would you like some tea before you leave?\n(Bạn uống chút trà trước khi đi nhé?)","Câu này có hình thức nghi vấn nhưng mang nghĩa mời, nên dùng some chứ không dùng any."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn lượng từ theo loại danh từ"},{"table":[["Lượng từ","Loại danh từ","Ví dụ"],["many / a few / few","danh từ đếm được số nhiều","many chairs"],["much / a little / little","danh từ không đếm được","much water"],["a lot of / lots of / plenty of","dùng được cho cả hai loại","a lot of friends / a lot of rice"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Do you have some question? → Đã sửa: Do you have any questions? — Câu nghi vấn thông thường dùng any và question phải ở dạng số nhiều."},{"p":"Chưa đúng: How much books do you read? → Đã sửa: How many books do you read? — Books đếm được nên phải dùng how many."},{"p":"Chưa đúng: I don't have some money. → Đã sửa: I don't have any money. — Câu phủ định dùng any, không dùng some."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Danh từ đi kèm là đếm được hay không đếm được."},{"p":"Câu đang ở thể khẳng định, phủ định hay nghi vấn."},{"p":"Some hay any đã đúng với thể của câu."},{"p":"Danh từ đếm được đã ở dạng số nhiều sau many và any."},{"p":"Một danh từ đếm được số ít chưa xác định vẫn cần a/an: offer an explanation."}]}],"id":"a1-08"},{"n":9,"title":"Adjectives & adverbs","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tính từ trả lời câu hỏi “như thế nào” về một danh từ, còn trạng từ chỉ cách thức trả lời câu hỏi “làm thế nào” về một hành động. Phần lớn trạng từ chỉ cách thức được tạo bằng cách thêm -ly vào tính từ, nhưng có một nhóm nhỏ bất quy tắc cần nhớ riêng."},{"p":"Cấu trúc chính: tính từ + danh từ | động từ + trạng từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She speaks English clearly. (Miêu tả danh từ | Miêu tả cách thực hiện hành động | Tăng giảm mức độ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Miêu tả danh từ: Tính từ đứng trước danh từ hoặc đứng sau các động từ nối như be, seem, look, feel. (a careful driver / The soup smells good.)"},{"p":"Miêu tả cách thực hiện hành động: Trạng từ chỉ cách thức thường đứng sau động từ hoặc sau tân ngữ. (He drives carefully.)"},{"p":"Tăng giảm mức độ: Trạng từ chỉ mức độ như very, quite, too đứng trước tính từ hoặc trạng từ khác. (very slowly / too expensive)"},{"p":"Phân biệt sau động từ nối: Sau động từ nối phải dùng tính từ, vì từ đó miêu tả chủ ngữ chứ không miêu tả hành động. (She looks happy. (không phải happily))"},{"p":"Ghi nhớ: Tính từ bổ nghĩa cho danh từ, trạng từ chỉ cách thức bổ nghĩa cho động từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: tính từ + danh từ | động từ + trạng từ"},{"table":[["Quy tắc / Vị trí","Dạng thức","Ví dụ"],["Thêm -ly","tính từ + -ly","quick → quickly, careful → carefully"],["Phụ âm + y → -ily","easy → easily","happy → happily"],["Bất quy tắc","good → well, fast → fast, hard → hard, late → late","She sings well."],["Vị trí","tính từ trước danh từ | trạng từ sau động từ hoặc sau tân ngữ","a slow train / He walks slowly."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định từ được bổ nghĩa: Bổ nghĩa cho danh từ thì dùng tính từ; bổ nghĩa cho động từ thì dùng trạng từ. (a careful driver ↔ drive carefully)"},{"p":"02. Kiểm tra động từ nối: Be, seem, look, feel, taste, smell, sound là động từ nối và đi với tính từ. (The music sounds beautiful.)"},{"p":"03. Tạo trạng từ theo quy tắc chính tả: Thêm -ly, đổi -y thành -ily và ghi nhớ nhóm bất quy tắc như good → well. (easy → easily)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trạng từ bổ nghĩa động từ","She speaks English clearly.\n(Cô ấy nói tiếng Anh rõ ràng.)","Clearly miêu tả cách nói, tức bổ nghĩa cho động từ speaks."],["Tính từ bổ nghĩa danh từ","He is a careful driver.\n(Anh ấy là một người lái xe cẩn thận.)","Careful đứng trước danh từ driver nên phải là tính từ."],["Sau động từ nối","The children look happy today.\n(Hôm nay các em trông vui vẻ.)","Look là động từ nối, miêu tả trạng thái của chủ ngữ, nên dùng tính từ happy."],["Trạng từ bất quy tắc","Minh plays the guitar well, and he learns fast.\n(Minh chơi ghi ta hay và học nhanh.)","Good có trạng từ là well; fast giữ nguyên hình thức ở cả hai từ loại."],["Trạng từ chỉ mức độ","The test was quite difficult, so we worked very carefully.\n(Bài kiểm tra khá khó nên chúng tôi làm rất cẩn thận.)","Quite bổ nghĩa cho tính từ difficult, very bổ nghĩa cho trạng từ carefully."],["Vị trí sau tân ngữ","Please read the instructions carefully.\n(Hãy đọc hướng dẫn thật cẩn thận.)","Khi động từ có tân ngữ, trạng từ chỉ cách thức đứng sau tân ngữ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Cặp tính từ - trạng từ dễ nhầm"},{"table":[["Cặp từ","Nghĩa / Phân loại","Ví dụ"],["good / well","tính từ / trạng từ","a good singer — She sings well."],["hard / hardly","chăm chỉ / hầu như không","He works hard. — He hardly works."],["late / lately","muộn / gần đây","She arrived late. — I haven't seen him lately."],["fast / fast","không có dạng -ly","a fast car — He runs fast."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She speaks English clear. → Đã sửa: She speaks English clearly. — Từ bổ nghĩa cho động từ speaks phải là trạng từ."},{"p":"Chưa đúng: He plays football very good. → Đã sửa: He plays football very well. — Trạng từ của good là well, không phải goodly."},{"p":"Chưa đúng: The soup tastes deliciously. → Đã sửa: The soup tastes delicious. — Taste là động từ nối, miêu tả chủ ngữ nên đi với tính từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Từ được bổ nghĩa là danh từ hay động từ."},{"p":"Động từ trong câu có phải động từ nối hay không."},{"p":"Dạng -ly đã viết đúng chính tả."},{"p":"Các cặp bất quy tắc như good/well không bị dùng lẫn."}]}],"id":"a1-09"},{"n":10,"title":"Adverbs of frequency","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Trạng từ chỉ tần suất cho biết một việc xảy ra thường xuyên đến mức nào. Vị trí của trạng từ phụ thuộc vào loại động từ: đứng trước động từ thường, đứng sau động từ to be và đứng giữa trợ động từ với động từ chính."},{"p":"Cấu trúc chính: S + trạng từ tần suất + V | S + be + trạng từ tần suất"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): He is often late. (Nói về thói quen và mức độ thường xuyên | Trả lời câu hỏi với how often | Nhấn mạnh mức độ hiếm)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nói về thói quen và mức độ thường xuyên: Các trạng từ này đi với thì hiện tại đơn để miêu tả nếp sinh hoạt. (I always have breakfast at home.)"},{"p":"Trả lời câu hỏi với how often: Trạng từ tần suất là câu trả lời trực tiếp cho how often. (How often do you swim? — I sometimes swim.)"},{"p":"Nhấn mạnh mức độ hiếm: Never, rarely, seldom đã mang nghĩa phủ định nên không dùng kèm not. (She never drinks coffee.)"},{"p":"Đặt ở đầu hoặc cuối câu: Sometimes, usually, often có thể đứng đầu hoặc cuối câu để nhấn mạnh; never thì không. (Sometimes we walk to school.)"},{"p":"Ghi nhớ: Trạng từ chỉ tần suất đứng trước động từ thường nhưng đứng sau động từ to be."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + trạng từ tần suất + V | S + be + trạng từ tần suất"},{"table":[["Trường hợp","Công thức / Thang mức độ","Ví dụ"],["Thang tần suất","always 100%, usually, often, sometimes, rarely/seldom, never 0%","I usually get up at six."],["Với động từ thường","S + trạng từ + V","She often reads at night."],["Với động từ to be","S + be + trạng từ","He is often late."],["Với trợ động từ","S + trợ động từ + trạng từ + V","I have never been to Hanoi."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định động từ chính của câu: Nếu động từ chính là to be thì trạng từ đứng sau nó; nếu là động từ thường thì trạng từ đứng trước. (is always ↔ always goes)"},{"p":"02. Tìm trợ động từ nếu có: Khi câu có do, have, will, can… thì trạng từ đặt giữa trợ động từ và động từ chính. (She can never remember.)"},{"p":"03. Kiểm tra nghĩa phủ định sẵn có: Never và rarely đã phủ định nên động từ giữ dạng khẳng định. (He never eats meat.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Sau động từ to be","He is often late for the first class.\n(Anh ấy thường trễ tiết đầu.)","Động từ chính là is nên often đứng sau; đặt often trước is là sai trật tự."],["Trước động từ thường","She usually walks to school.\n(Cô ấy thường đi bộ đến trường.)","Walks là động từ thường nên usually đứng trước nó."],["Giữa trợ động từ và động từ chính","I have never been to Da Lat.\n(Tôi chưa bao giờ đến Đà Lạt.)","Have là trợ động từ, never chen vào giữa have và been."],["Nghĩa phủ định sẵn có","My grandmother never drinks coffee in the evening.\n(Bà tôi không bao giờ uống cà phê vào buổi tối.)","Never đã mang nghĩa phủ định nên động từ vẫn ở dạng khẳng định drinks."],["Đứng đầu câu","Sometimes we study together at the library.\n(Thỉnh thoảng chúng tôi học cùng nhau ở thư viện.)","Sometimes được phép đứng đầu câu để nhấn mạnh; never thì không dùng như vậy trong câu bình thường."],["Trả lời how often","How often do you play badminton? — I rarely play these days.\n(Bạn chơi cầu lông thường xuyên không? — Dạo này tôi ít chơi.)","Rarely đứng trước động từ chính play trong câu trả lời."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Vị trí trạng từ theo loại động từ"},{"table":[["Loại động từ","Vị trí trạng từ","Ví dụ"],["động từ to be","trạng từ đứng sau","They are always busy."],["động từ thường","trạng từ đứng trước","They always work hard."],["có trợ động từ","trạng từ đứng giữa","They will always remember."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: He often is late. → Đã sửa: He is often late. — Với động từ to be, trạng từ tần suất đứng sau động từ."},{"p":"Chưa đúng: She doesn't never come late. → Đã sửa: She never comes late. — Never đã phủ định nên không dùng thêm doesn't."},{"p":"Chưa đúng: I go always early. → Đã sửa: I always go early. — Với động từ thường, trạng từ đứng trước động từ, không đứng sau."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ chính là to be hay động từ thường."},{"p":"Câu có trợ động từ cần chen trạng từ vào giữa hay không."},{"p":"Never và rarely không bị dùng kèm not."},{"p":"Trạng từ được chọn đúng mức độ tần suất muốn diễn đạt."}]}],"id":"a1-10"},{"n":11,"title":"Prepositions of time & place","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ba giới từ at, on, in chiếm phần lớn các lỗi giới từ ở trình độ A1. Có một quy luật chung giúp nhớ: at dùng cho điểm, on dùng cho đường hoặc bề mặt, in dùng cho phạm vi bao quanh. Quy luật này đúng cho cả thời gian và nơi chốn."},{"p":"Cấu trúc chính: at 7 | on Monday | in July | under the table"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The class starts at nine on Monday. (Điểm thời gian và địa điểm cụ thể | Chỉ ngày, thứ và bề mặt | Khoảng thời gian và không gian bao quanh)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Điểm thời gian và địa điểm cụ thể: At đi với giờ và với những nơi được coi là một điểm trên bản đồ. (at 7 o'clock / at the bus stop)"},{"p":"Chỉ ngày, thứ và bề mặt: On đi với thứ, ngày tháng và với vật nằm trên một mặt phẳng. (on Monday / on 2 September / on the wall)"},{"p":"Khoảng thời gian và không gian bao quanh: In đi với tháng, năm, mùa và với nơi có ranh giới bao quanh. (in July / in 2026 / in the room)"},{"p":"Chỉ vị trí tương đối: Các giới từ như under, behind, between, next to, in front of chỉ quan hệ vị trí giữa hai vật. (The cat is under the table.)"},{"p":"Hạn chót, mốc và khoảng: By nói việc phải xong trước một thời điểm; since nói việc bắt đầu từ mốc nào và còn kéo dài; for đo việc kéo dài bao lâu. Ba giới từ này trả lời ba câu hỏi khác nhau về thời gian. (Submissions must arrive by Friday. / The index has fallen since 2008. / The experiment ran for eighteen months.)"},{"p":"Ghi nhớ: At chỉ điểm, on chỉ ngày và bề mặt, in chỉ khoảng thời gian và không gian bên trong."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: at 7 | on Monday | in July | under the table"},{"table":[["Nhóm giới từ","Công thức","Ví dụ"],["Thời gian","at + giờ | on + ngày/thứ | in + tháng/năm/mùa","at 9.30, on Friday, in April"],["Nơi chốn","at + điểm | on + bề mặt | in + không gian kín","at the door, on the table, in the box"],["Vị trí tương đối","under, over, behind, in front of, between, next to, opposite","between the bank and the post office"],["Cụm cố định","at night, in the morning, on time, at the weekend","I study best at night."],["by · since · for","by + hạn chót (trước hoặc đúng lúc đó) | since + mốc bắt đầu | for + độ dài khoảng thời gian","by the end of March, since 2008, for eighteen months"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định loại thông tin đi sau: Cùng một giới từ nhưng cách chọn sẽ dựa trên loại thông tin đi sau nó. (at 7 (thời gian) / at school (nơi chốn))"},{"p":"02. Áp quy luật điểm, bề mặt, phạm vi: Thông tin càng cụ thể và hẹp thì càng gần at, càng rộng và bao quanh thì càng gần in. (at 7 → on Monday → in July)"},{"p":"03. Ghi nhớ các cụm cố định: At night, in the morning, on time là những cụm phải học nguyên khối. (in the afternoon, nhưng at night)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Giờ và thứ","The class starts at nine on Monday.\n(Lớp bắt đầu lúc chín giờ vào thứ Hai.)","Giờ dùng at, thứ dùng on; hai giới từ xuất hiện trong cùng một câu mà không thay thế nhau được."],["Năm và tháng","She was born in July 2010.\n(Cô ấy sinh vào tháng Bảy năm 2010.)","Tháng và năm đều là khoảng thời gian dài nên dùng in."],["Bề mặt","The keys are on the table next to the lamp.\n(Chìa khoá ở trên bàn, cạnh cái đèn.)","On chỉ vật nằm trên một mặt phẳng; next to chỉ vị trí kề bên."],["Không gian bao quanh","The children are playing in the garden.\n(Các em đang chơi trong vườn.)","Garden được hiểu là một khu vực có ranh giới nên dùng in."],["Vị trí tương đối","The post office is between the bank and the market.\n(Bưu điện nằm giữa ngân hàng và chợ.)","Between luôn đi với hai mốc, nối bằng and."],["Cụm cố định","I usually read in the evening, but I never study at night.\n(Tôi thường đọc sách vào buổi tối, nhưng không bao giờ học vào đêm khuya.)","In the evening theo quy luật, còn at night là cụm cố định ngoại lệ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Cùng danh từ, khác giới từ"},{"table":[["Cụm giới từ","Nghĩa","Ví dụ"],["in the corner","góc bên trong phòng","The desk is in the corner."],["at the corner","góc phố, điểm giao nhau","Turn left at the corner."],["on the corner","ngay tại góc, trên mặt góc phố","There is a shop on the corner."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The class starts in nine. → Đã sửa: The class starts at nine. — Giờ là một điểm thời gian nên dùng at."},{"p":"Chưa đúng: I was born on July. → Đã sửa: I was born in July. — Tháng là khoảng thời gian dài nên dùng in; on chỉ dùng với ngày cụ thể."},{"p":"Chưa đúng: She lives at Hue. → Đã sửa: She lives in Hue. — Thành phố được coi là không gian bao quanh nên dùng in."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Thông tin đi sau giới từ là điểm, bề mặt hay phạm vi."},{"p":"Giới từ thời gian và giới từ nơi chốn không bị dùng lẫn."},{"p":"Các cụm cố định đã được dùng nguyên khối."},{"p":"Giới từ chỉ vị trí tương đối đi đủ các mốc cần thiết."}]}],"id":"a1-11"},{"n":12,"title":"Present simple","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hiện tại đơn không nói về thời điểm đang nói, mà nói về điều luôn đúng hoặc lặp lại đều đặn: thói quen, nếp sinh hoạt, sự thật hiển nhiên và lịch trình cố định. Dấu hiệu hình thức duy nhất cần nhớ là đuôi -s/-es ở ngôi thứ ba số ít."},{"p":"Cấu trúc chính: S + V(s/es)"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): My brother studies every evening. (Thói quen và việc lặp lại | Sự thật hiển nhiên và chân lí | Trạng thái và cảm nhận lâu dài)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thói quen và việc lặp lại: Thường đi kèm trạng từ tần suất hoặc cụm chỉ chu kì như every day, twice a week. (I get up at six every morning.)"},{"p":"Sự thật hiển nhiên và chân lí: Điều luôn đúng không phụ thuộc thời điểm nói. (Water boils at 100 degrees.)"},{"p":"Trạng thái và cảm nhận lâu dài: Các động từ chỉ trạng thái như know, like, belong thường dùng ở hiện tại đơn. (She likes classical music.)"},{"p":"Lịch trình, thời khoá biểu: Dùng cho sự việc tương lai đã được ấn định bằng thời khoá biểu hoặc giờ tàu xe. (The train leaves at 6.15 tomorrow.)"},{"p":"Ghi nhớ: Dùng cho thói quen, sự thật và lịch trình; chủ ngữ số ít ngôi thứ ba thêm -s hoặc -es."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + V(s/es)"},{"table":[["Dạng thức","Công thức / Quy tắc","Ví dụ"],["Khẳng định","I/you/we/they + V | he/she/it + V-s/es","She works here."],["Phủ định","S + do/does not + V nguyên mẫu","He does not work here."],["Nghi vấn","Do/Does + S + V nguyên mẫu?","Does she work here?"],["Chính tả đuôi -s","-s | -es sau -s/-sh/-ch/-x/-o | phụ âm + y → -ies","go → goes, watch → watches, study → studies"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định ngôi và số của chủ ngữ: He, she, it và mọi danh từ số ít đều kéo theo đuôi -s hoặc -es ở động từ. (My brother (= he) → studies)"},{"p":"02. Áp quy tắc chính tả cho đuôi -s: Sau âm xuýt thêm -es; phụ âm + y đổi y thành i rồi thêm -es; have có dạng riêng là has. (study → studies / have → has)"},{"p":"03. Dùng do/does trong câu phủ định và nghi vấn: Khi đã có does thì động từ chính trở về dạng nguyên mẫu, không giữ đuôi -s. (Does he live here?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Thói quen","My brother studies every evening.\n(Anh trai tôi học mỗi buổi tối.)","My brother là ngôi thứ ba số ít nên study thành studies; every evening là dấu hiệu lặp lại."],["Nếp sinh hoạt","Tom drinks coffee every morning before work.\n(Tom uống cà phê mỗi sáng trước khi đi làm.)","Đuôi -s ở drinks là dấu hiệu duy nhất cho biết chủ ngữ là ngôi thứ ba số ít."],["Sự thật hiển nhiên","Water boils at one hundred degrees Celsius.\n(Nước sôi ở một trăm độ C.)","Điều luôn đúng nên dùng hiện tại đơn, không dùng hiện tại tiếp diễn."],["Phủ định","She does not eat meat, but she eats fish.\n(Cô ấy không ăn thịt, nhưng có ăn cá.)","Sau does not, động từ trở về nguyên mẫu eat; ở vế khẳng định thì vẫn là eats."],["Nghi vấn","Does your sister work in Hanoi?\n(Chị bạn làm việc ở Hà Nội à?)","Does đã mang dấu hiệu ngôi thứ ba số ít nên work không thêm -s."],["Lịch trình","The last bus leaves at ten past nine.\n(Chuyến xe buýt cuối rời bến lúc chín giờ mười.)","Hiện tại đơn dùng cho giờ tàu xe, dù sự việc thuộc tương lai."],["Chủ ngữ số nhiều","The students read scientific articles every week.\n(Sinh viên đọc các bài báo khoa học mỗi tuần.)","Chủ ngữ số nhiều giữ nguyên dạng gốc: the students read, còn reads chỉ dùng với he, she, it."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hiện tại đơn và hiện tại tiếp diễn"},{"table":[["Thì / Nhóm từ","Cách dùng","Ví dụ"],["Hiện tại đơn","thói quen, điều luôn đúng","He works in a bank."],["Hiện tại tiếp diễn","đang xảy ra lúc nói, tạm thời","He is working at home this week."],["Động từ chỉ trạng thái","thường chỉ dùng ở hiện tại đơn","I know the answer. (không dùng I am knowing)"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: My brother study every evening. → Đã sửa: My brother studies every evening. — Chủ ngữ ngôi thứ ba số ít đòi hỏi đuôi -s hoặc -es ở động từ."},{"p":"Chưa đúng: Does he lives here? → Đã sửa: Does he live here? — Does đã mang dấu hiệu ngôi thứ ba số ít nên động từ chính về dạng nguyên mẫu."},{"p":"Chưa đúng: She don't like tea. → Đã sửa: She doesn't like tea. — Ngôi thứ ba số ít dùng trợ động từ does, không dùng do."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Chủ ngữ có thuộc ngôi thứ ba số ít hay không."},{"p":"Đuôi -s hoặc -es viết đúng chính tả."},{"p":"Câu phủ định và nghi vấn dùng do hoặc does đúng ngôi."},{"p":"Động từ chính trở về nguyên mẫu khi đã có do/does."}]}],"id":"a1-12"},{"n":13,"title":"Like, love & hate + V-ing","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Để nói về sở thích, tiếng Anh dùng một động từ chỉ cảm xúc rồi đến động từ ở dạng V-ing. Điểm dễ sai là để động từ thứ hai ở dạng nguyên mẫu như trong tiếng Việt. Cũng cần phân biệt hai cấu trúc gần nhau. Like nói về sở thích lâu dài, còn would like là lời mời hoặc mong muốn lúc này và đi với động từ nguyên mẫu có to."},{"p":"Cấu trúc chính: like/love/enjoy/hate + V-ing | would like + to-V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She likes reading comics. (Nói về sở thích lâu dài | Nói về điều không thích | Mời hoặc nêu mong muốn lúc này)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nói về sở thích lâu dài: Like, love, enjoy, hate đi với V-ing. (I enjoy swimming in the morning.)"},{"p":"Nói về điều không thích: Dùng don't like hoặc hate, động từ theo sau vẫn ở dạng V-ing. (He doesn't like waiting.)"},{"p":"Mời hoặc nêu mong muốn lúc này: Would like đi với động từ nguyên mẫu có to, không đi với V-ing. (Would you like to join us?)"},{"p":"Nêu mức độ yêu thích: Thêm very much, a lot ở cuối câu hoặc dùng love thay cho like. (I like cooking very much.)"},{"p":"Ghi nhớ: Sau like, love, enjoy, hate dùng V-ing; riêng would like đi với động từ nguyên mẫu có to."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: like/love/enjoy/hate + V-ing | would like + to-V"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Sở thích","S + like/love/enjoy/hate + V-ing","They love travelling."],["Phủ định","S + do/does not like + V-ing","She doesn't like getting up early."],["Nghi vấn","Do/Does + S + like + V-ing?","Do you like dancing?"],["would like","S + would like + to-V","I would like to book a table."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn động từ chỉ cảm xúc phù hợp: Love mạnh hơn like, hate là mức phủ định mạnh nhất. (love ↔ like ↔ don't like ↔ hate)"},{"p":"02. Đưa động từ thứ hai về dạng V-ing: Giữ đúng quy tắc chính tả khi thêm -ing. (swim → swimming /write → writing)"},{"p":"03. Phân biệt like với would like: Like nói về sở thích chung; would like nói về mong muốn ngay lúc này và đi với to-V. (I like coffee. ↔ I would like a coffee.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Sở thích lâu dài","She likes reading comics in the evening.\n(Cô ấy thích đọc truyện tranh vào buổi tối.)","Sau likes là dạng V-ing reading, không phải read."],["Mức độ mạnh","My brother loves playing football with his friends.\n(Anh trai tôi rất thích chơi bóng với bạn bè.)","Love mạnh hơn like, nhưng dạng động từ theo sau vẫn là V-ing."],["Điều không thích","He doesn't like waiting in long queues.\n(Anh ấy không thích chờ xếp hàng dài.)","Doesn't like vẫn đi với V-ing; động từ chỉ cảm xúc là like mới chịu tác động của trợ động từ."],["Mức phủ định mạnh","I hate getting up before six o'clock.\n(Tôi rất ghét phải thức dậy trước sáu giờ.)","Hate là mức phủ định mạnh nhất trong nhóm, cũng đi với V-ing."],["Lời mời","Would you like to join us for lunch?\n(Bạn dùng cơm trưa với chúng tôi nhé?)","Would like là lời mời và bắt buộc đi với động từ nguyên mẫu có to."],["Phân biệt hai cấu trúc","I like tea, but right now I would like to drink water.\n(Tôi thích trà, nhưng lúc này tôi muốn uống nước.)","Like nói về sở thích chung, would like nói về mong muốn tại thời điểm nói."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: like và would like"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["like + V-ing","sở thích lâu dài","I like swimming."],["would like + to-V","mong muốn ngay lúc này","I would like to swim now."],["Would you like …?","lời mời lịch sự","Would you like some tea?"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She likes read comics. → Đã sửa: She likes reading comics. — Sau like là động từ ở dạng V-ing."},{"p":"Chưa đúng: Would you like joining us? → Đã sửa: Would you like to join us? — Would like đi với động từ nguyên mẫu có to, không đi với V-ing."},{"p":"Chưa đúng: I am liking this song. → Đã sửa: I like this song. — Like là động từ chỉ trạng thái nên không dùng ở dạng tiếp diễn."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ sau like, love, enjoy, hate ở dạng V-ing."},{"p":"Would like đi với động từ nguyên mẫu có to."},{"p":"Đuôi -ing viết đúng chính tả."},{"p":"Like không dùng ở dạng tiếp diễn."}]}],"id":"a1-13"},{"n":14,"title":"Present continuous","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hiện tại tiếp diễn gồm hai phần không thể thiếu: động từ to be chia theo chủ ngữ và động từ chính ở dạng V-ing. Thì này diễn tả hành động đang xảy ra ngay lúc nói, tình huống tạm thời trong giai đoạn này, hoặc kế hoạch đã sắp xếp cho tương lai gần."},{"p":"Cấu trúc chính: S + am/is/are + V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): They are waiting for the bus. (Hành động đang xảy ra lúc nói | Tình huống tạm thời | Kế hoạch đã sắp xếp)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hành động đang xảy ra lúc nói: Thường đi với now, at the moment, right now. (I am reading now.)"},{"p":"Tình huống tạm thời: Dùng cho giai đoạn hiện tại, khác với nếp thường lệ. (She is staying with her aunt this month.)"},{"p":"Kế hoạch đã sắp xếp: Khi đã hẹn thời gian và địa điểm cụ thể, thì hiện tại tiếp diễn có thể chỉ tương lai gần. (We are meeting Hoa at six tonight.)"},{"p":"Thay đổi đang diễn tiến: Dùng với các động từ chỉ sự biến đổi như get, become, grow, improve. (The weather is getting colder.)"},{"p":"Ghi nhớ: Dùng cho hành động đang diễn ra lúc nói hoặc tình huống tạm thời."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + am/is/are + V-ing"},{"table":[["Dạng thức","Công thức / Quy tắc","Ví dụ"],["Khẳng định","S + am/is/are + V-ing","They are waiting outside."],["Phủ định","S + am/is/are + not + V-ing","He is not working today."],["Nghi vấn","Am/Is/Are + S + V-ing?","Are you listening?"],["Chính tả V-ing","bỏ -e | nhân đôi phụ âm cuối | -ie → -ying","write → writing, sit → sitting, lie → lying"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chia động từ to be theo chủ ngữ: I am, he/she/it is, you/we/they are - thiếu to be là lỗi phổ biến nhất của thì này. (They are waiting.)"},{"p":"02. Thêm -ing vào động từ chính: Bỏ -e cuối trước khi thêm -ing; nhân đôi phụ âm cuối khi động từ một âm tiết kết thúc bằng nguyên âm + phụ âm. (make → making / run → running)"},{"p":"03. Kiểm tra nhóm động từ chỉ trạng thái: Know, like, want, belong, understand hầu như không dùng ở dạng tiếp diễn. (I want it. (không dùng I am wanting it))"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Đang xảy ra lúc nói","They are waiting for the bus right now.\n(Họ đang đợi xe buýt ngay lúc này.)","Đủ cả hai thành phần are và waiting; thiếu are là câu sai ngữ pháp."],["Tình huống tạm thời","I am staying with my grandparents this week.\n(Tuần này tôi đang ở nhà ông bà.)","Việc này chỉ diễn ra trong giai đoạn hiện tại, không phải nếp thường ngày."],["Phủ định","He is not studying at the moment; he is having lunch.\n(Lúc này anh ấy không học, anh ấy đang ăn trưa.)","Not đặt giữa to be và V-ing; have ở nghĩa “ăn” thì dùng được dạng tiếp diễn."],["Nghi vấn","Are you listening to me?\n(Bạn có đang nghe tôi nói không?)","Câu hỏi đảo to be lên trước chủ ngữ, động từ chính giữ dạng V-ing."],["Kế hoạch đã hẹn","We are meeting Hoa at six o'clock tonight.\n(Sáu giờ tối nay, chúng tôi gặp Hoa.)","Kế hoạch đã ấn định thời gian và người tham gia, nên thì hiện tại tiếp diễn chỉ tương lai gần."],["Thay đổi đang diễn tiến","The weather is getting colder every day.\n(Thời tiết mỗi ngày một lạnh hơn.)","Get chỉ sự biến đổi dần nên rất hay dùng ở dạng tiếp diễn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Dấu hiệu thời gian của hai thì hiện tại"},{"table":[["Dấu hiệu","Thì sử dụng","Ví dụ"],["now / at the moment / today","hiện tại tiếp diễn","She is cooking now."],["every day / usually / always","hiện tại đơn","She cooks every day."],["this week / these days","tạm thời, dùng tiếp diễn","He is working from home this week."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: They waiting for the bus. → Đã sửa: They are waiting for the bus. — Thiếu động từ to be thì câu chưa thành thì hiện tại tiếp diễn."},{"p":"Chưa đúng: I am read a book now. → Đã sửa: I am reading a book now. — Sau to be phải là dạng V-ing, không phải động từ nguyên mẫu."},{"p":"Chưa đúng: I am knowing the answer. → Đã sửa: I know the answer. — Know là động từ chỉ trạng thái, không dùng ở dạng tiếp diễn."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu có đủ to be chia theo chủ ngữ."},{"p":"Động từ chính ở dạng V-ing và viết đúng chính tả."},{"p":"Động từ không thuộc nhóm chỉ trạng thái."},{"p":"Dấu hiệu thời gian phù hợp với nghĩa đang diễn ra hoặc tạm thời."}]}],"id":"a1-14"},{"n":15,"title":"Basic word order","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tiếng Việt cho phép đảo trạng ngữ khá tự do, còn tiếng Anh thì không. Trật tự mặc định là chủ ngữ, động từ, tân ngữ; sau đó mới đến trạng ngữ và trong nhóm trạng ngữ thì nơi chốn đứng trước thời gian. Quan trọng nhất là không được chen bất cứ thành phần nào vào giữa động từ và tân ngữ của nó."},{"p":"Cấu trúc chính: S + V + O + trạng ngữ nơi chốn + trạng ngữ thời gian"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I study English at home every evening. (Câu kể cơ bản | Thêm trạng ngữ nơi chốn và thời gian | Đưa trạng ngữ thời gian lên đầu câu)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Câu kể cơ bản: Chủ ngữ, động từ, tân ngữ đi liền nhau thành một khối. (My sister plays the piano.)"},{"p":"Thêm trạng ngữ nơi chốn và thời gian: Nơi chốn đứng trước thời gian, cả hai đều ở cuối câu. (We met Nam at the station yesterday.)"},{"p":"Đưa trạng ngữ thời gian lên đầu câu: Trạng ngữ thời gian được phép lên đầu câu và có dấu phẩy theo sau. (Every evening, I study English.)"},{"p":"Câu có hai tân ngữ: Tân ngữ gián tiếp chỉ người đứng trước tân ngữ trực tiếp chỉ vật. (She gave me a book.)"},{"p":"Ghi nhớ: Giữ trật tự chủ ngữ, động từ, tân ngữ rồi mới đến trạng ngữ nơi chốn và thời gian."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + V + O + trạng ngữ nơi chốn + trạng ngữ thời gian"},{"table":[["Mẫu câu","Công thức","Ví dụ"],["Trật tự mặc định","S + V + O + nơi chốn + thời gian","They watched a film at home last night."],["Hai tân ngữ","S + V + O người + O vật","He sent his mother a letter."],["Hai tân ngữ với giới từ","S + V + O vật + to/for + người","He sent a letter to his mother."],["Trạng ngữ lên đầu câu","trạng ngữ thời gian, S + V + O","Last night, we watched a film."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đặt chủ ngữ, động từ, tân ngữ liền nhau: Không chen trạng ngữ vào giữa động từ và tân ngữ của nó. (I study English, không phải I study every evening English)"},{"p":"02. Xếp nơi chốn trước thời gian: Nếu có cả hai loại, nơi chốn luôn đứng trước thời gian. (at home every evening)"},{"p":"03. Kiểm tra hai tân ngữ: Người nhận đứng trước vật nếu không có giới từ; có giới từ thì vật đứng trước. (give me the key / give the key to me)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trật tự mặc định","I study English at home every evening.\n(Tôi học tiếng Anh ở nhà mỗi tối.)","Study và English đi liền nhau, rồi mới tới nơi chốn at home và thời gian every evening."],["Trạng ngữ lên đầu","Every evening, I study English at home.\n(Mỗi tối tôi học tiếng Anh ở nhà.)","Trạng ngữ thời gian được phép lên đầu câu và có dấu phẩy sau nó."],["Nơi chốn trước thời gian","We met Nam at the station yesterday.\n(Chúng tôi gặp Nam ở nhà ga hôm qua.)","Nếu đổi thành yesterday at the station thì câu nghe không tự nhiên trong tiếng Anh chuẩn."],["Hai tân ngữ không có giới từ","She gave me a new dictionary.\n(Cô ấy cho tôi một quyển từ điển mới.)","Người nhận me đứng trước vật a new dictionary."],["Hai tân ngữ có giới từ","She gave a new dictionary to her younger brother.\n(Cô ấy cho em trai một quyển từ điển mới.)","Khi có giới từ to, trật tự đảo lại: vật đứng trước, người nhận đứng sau."],["Trạng ngữ tần suất","He usually does his homework in the library after school.\n(Cậu ấy thường làm bài tập ở thư viện sau giờ học.)","Trạng ngữ tần suất usually đứng trước động từ, còn nơi chốn và thời gian vẫn ở cuối câu."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Vị trí của các loại trạng ngữ"},{"table":[["Loại trạng ngữ","Vị trí","Ví dụ"],["trạng ngữ tần suất","trước động từ thường, sau động từ to be","She always arrives early."],["trạng ngữ nơi chốn","sau tân ngữ","He left his bag in the car."],["trạng ngữ thời gian","sau nơi chốn hoặc đầu câu","…in the car this morning."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I study every evening English at home. → Đã sửa: I study English at home every evening. — Không chen trạng ngữ thời gian vào giữa động từ và tân ngữ."},{"p":"Chưa đúng: We met yesterday Nam at the station. → Đã sửa: We met Nam at the station yesterday. — Tân ngữ Nam phải đứng ngay sau động từ met."},{"p":"Chưa đúng: She gave to me a new dictionary. → Đã sửa: She gave me a new dictionary. — Khi người nhận đứng ngay sau động từ thì không dùng giới từ to."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ và tân ngữ đứng liền nhau."},{"p":"Trạng ngữ nơi chốn đứng trước trạng ngữ thời gian."},{"p":"Trạng ngữ thời gian đưa lên đầu câu thì có dấu phẩy."},{"p":"Hai tân ngữ xếp đúng thứ tự theo việc có giới từ hay không."}]}],"id":"a1-15"},{"n":16,"title":"Negatives & questions","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Động từ thường không tự tạo được câu phủ định hay câu hỏi, nên tiếng Anh dùng trợ động từ do hoặc does gánh vai trò đó. Khi trợ động từ đã mang dấu hiệu ngôi và số, động từ chính lập tức trở về dạng nguyên mẫu - đây là nguyên tắc chi phối mọi câu phủ định và nghi vấn ở hiện tại đơn."},{"p":"Cấu trúc chính: Do/Does + S + V? | S + do/does not + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Does she work here? (Phủ định một thói quen hoặc sự thật | Đặt câu hỏi có hoặc không | Đặt câu hỏi với từ hỏi)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Phủ định một thói quen hoặc sự thật: Dùng do not hoặc does not trước động từ nguyên mẫu. (I do not drink coffee.)"},{"p":"Đặt câu hỏi có hoặc không: Đưa do hoặc does lên đầu câu, trước chủ ngữ. (Do you live near here?)"},{"p":"Đặt câu hỏi với từ hỏi: Từ hỏi đứng trước trợ động từ, phần còn lại giữ trật tự câu hỏi. (Where does she work?)"},{"p":"Trả lời ngắn: Câu trả lời ngắn nhắc lại trợ động từ chứ không nhắc lại động từ chính. (Do you smoke? — No, I don't.)"},{"p":"Ghi nhớ: Với động từ thường ở hiện tại đơn, dùng do hoặc does để tạo câu phủ định và câu hỏi."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Do/Does + S + V? | S + do/does not + V"},{"table":[["Dạng câu","Công thức","Ví dụ"],["Phủ định","I/you/we/they + do not (don't) + V | he/she/it + does not (doesn't) + V","She doesn't like tea."],["Nghi vấn","Do/Does + S + V nguyên mẫu?","Does he live here?"],["Câu hỏi có từ hỏi","Wh- + do/does + S + V?","What do you do at weekends?"],["Trả lời ngắn","Yes, S + do/does. / No, S + don't/doesn't.","Yes, she does."],["Câu hỏi với be","Am/Is/Are + chủ ngữ + phần còn lại? (be tự đảo, không mượn do/does)","Is the dataset freely available?"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn do hay does theo chủ ngữ: He, she, it và danh từ số ít dùng does; các chủ ngữ còn lại dùng do. (Does your brother…? / Do your friends…?)"},{"p":"02. Đưa động từ chính về dạng nguyên mẫu: Đuôi -s đã chuyển sang trợ động từ does, nên động từ chính không giữ -s nữa. (Does she work? (không phải works))"},{"p":"03. Đặt từ hỏi trước trợ động từ: Trật tự là từ hỏi + trợ động từ + chủ ngữ + động từ chính. (Where do you live?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nghi vấn ngôi thứ ba","Does she work here?\n(Cô ấy làm việc ở đây à?)","Does mang dấu hiệu ngôi thứ ba số ít nên work giữ dạng nguyên mẫu."],["Phủ định số nhiều","They do not play tennis on Sundays.\n(Họ không chơi quần vợt vào Chủ nhật.)","Chủ ngữ số nhiều dùng do not; dạng rút gọn là don't."],["Phủ định ngôi thứ ba","My father doesn't drink tea in the evening.\n(Bố tôi không uống trà vào buổi tối.)","Doesn't đã mang -s nên drink về nguyên mẫu."],["Câu hỏi có từ hỏi","Where does your sister study?\n(Chị bạn học ở đâu?)","Trật tự: từ hỏi where, trợ động từ does, chủ ngữ your sister, rồi động từ nguyên mẫu study."],["Trả lời ngắn","Do you live near the school? — Yes, I do.\n(Bạn ở gần trường không? — Có.)","Câu trả lời ngắn nhắc lại trợ động từ do, không nhắc lại live."],["Câu hỏi về nghề nghiệp","What does your mother do?\n(Mẹ bạn làm nghề gì?)","Does là trợ động từ, do thứ hai là động từ chính mang nghĩa “làm”."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Cách hỏi với động từ thường và to be"},{"table":[["Loại động từ","Cách tạo câu hỏi/phủ định","Ví dụ"],["động từ thường","cần do/does","Do you like it? / I don't like it."],["động từ to be","tự đảo, không cần do","Are you ready? / I'm not ready."],["động từ khuyết thiếu","tự đảo như to be","Can you swim? / I can't swim."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Does she works here? → Đã sửa: Does she work here? — Khi đã có does, động từ chính không giữ đuôi -s."},{"p":"Chưa đúng: She not like tea. → Đã sửa: She does not like tea. — Động từ thường cần trợ động từ does để phủ định, không thể thêm not trực tiếp."},{"p":"Chưa đúng: Where she does live? → Đã sửa: Where does she live? — Trợ động từ phải đứng ngay sau từ hỏi và trước chủ ngữ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Trợ động từ do hoặc does chọn đúng theo chủ ngữ."},{"p":"Động từ chính ở dạng nguyên mẫu, không còn đuôi -s."},{"p":"Từ hỏi đứng trước trợ động từ."},{"p":"Câu trả lời ngắn nhắc lại trợ động từ, không nhắc lại động từ chính."},{"p":"Câu có am/is/are thì đảo chính nó lên đầu, không thêm do/does."}]}],"id":"a1-16"},{"n":17,"title":"Wh- questions","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Câu hỏi với từ hỏi dùng để lấy thông tin cụ thể chứ không phải để xác nhận có hoặc không. Trật tự gồm bốn phần: từ hỏi, trợ động từ, chủ ngữ, động từ chính. Có một ngoại lệ quan trọng: khi who hoặc what chính là chủ ngữ của câu thì không dùng trợ động từ và trật tự giữ như câu kể."},{"p":"Cấu trúc chính: Wh- + trợ động từ + S + V? | Who + V?"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Where do you live? (Hỏi về nơi chốn, thời gian, lí do | Hỏi về người và vật | Hỏi khi từ hỏi làm chủ ngữ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hỏi về nơi chốn, thời gian, lí do: Where, when, why đứng đầu câu rồi đến trợ động từ. (Why did she leave early?)"},{"p":"Hỏi về người và vật: Who hỏi về người, what hỏi về vật hoặc sự việc. (What do you want?)"},{"p":"Hỏi khi từ hỏi làm chủ ngữ: Không dùng do, does, did; động từ chia theo từ hỏi như với ngôi thứ ba số ít. (Who called you? / What happened?)"},{"p":"Hỏi về cách thức, số lượng và lựa chọn: How, how many, how much, which đi kèm một danh từ hoặc tính từ. (How many brothers do you have? / Which bag is yours?)"},{"p":"Ghi nhớ: Từ hỏi đứng đầu câu, tiếp đến trợ động từ rồi chủ ngữ; riêng who làm chủ ngữ thì không cần trợ động từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Wh- + trợ động từ + S + V? | Who + V?"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Trật tự chuẩn","Wh- + do/does/did + S + V nguyên mẫu?","Where do you live?"],["Với động từ to be","Wh- + am/is/are/was/were + S?","Where is your sister?"],["Từ hỏi làm chủ ngữ","Who/What + V (không có trợ động từ)","Who wants some tea?"],["Từ hỏi có danh từ theo sau","How many/How much/What/Which + danh từ + trợ động từ + S + V?","What time does the shop open?"],["Whose + danh từ","Whose + danh từ + câu hỏi: hỏi ai sở hữu thứ đó","Whose dataset was used for the final analysis?"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn từ hỏi theo thông tin cần biết: Where cho nơi chốn, when cho thời gian, why cho lí do, how cho cách thức. (How do you go to school?)"},{"p":"02. Đặt trợ động từ ngay sau từ hỏi: Động từ thường dùng do, does hoặc did; động từ to be thì tự đảo lên vị trí đó. (Where does he work? / Where is he?)"},{"p":"03. Xét vai trò của từ hỏi: Nếu who hoặc what chính là người hoặc vật thực hiện hành động thì bỏ trợ động từ. (Who broke the window?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Hỏi nơi chốn","Where do you live?\n(Bạn sống ở đâu?)","Đủ bốn phần: từ hỏi where, trợ động từ do, chủ ngữ you, động từ nguyên mẫu live."],["Với động từ to be","Where is your sister this afternoon?\n(Chiều nay chị bạn ở đâu?)","Động từ to be tự đảo lên sau từ hỏi, không cần thêm do."],["Hỏi lí do","Why did she leave the party so early?\n(Sao cô ấy về sớm vậy?)","Did mang dấu hiệu quá khứ nên leave giữ dạng nguyên mẫu."],["Từ hỏi làm chủ ngữ","Who broke the window?\n(Ai làm vỡ cửa sổ?)","Who chính là người thực hiện hành động nên không dùng did và động từ chia ở quá khứ đơn."],["What làm chủ ngữ","What happened at the meeting?\n(Chuyện gì đã xảy ra ở cuộc họp?)","What là chủ ngữ nên trật tự giữ như câu kể và không có trợ động từ."],["Từ hỏi có danh từ theo sau","What time does the library close?\n(Thư viện đóng cửa lúc mấy giờ?)","Cụm what time đứng trọn ở đầu câu, rồi mới đến trợ động từ does."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Who làm chủ ngữ và who làm tân ngữ"},{"table":[["Câu hỏi","Phân tích vai trò","Câu trả lời"],["Who called you?","who là chủ ngữ, không có trợ động từ","Nam called me."],["Who did you call?","who là tân ngữ, có trợ động từ did","I called Nam."],["What happened?","what là chủ ngữ","An accident happened."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Where you live? → Đã sửa: Where do you live? — Câu hỏi với động từ thường cần trợ động từ do hoặc does."},{"p":"Chưa đúng: Who did break the window? → Đã sửa: Who broke the window? — Khi who làm chủ ngữ thì không dùng trợ động từ did."},{"p":"Chưa đúng: Where does she lives? → Đã sửa: Where does she live? — Does đã mang dấu hiệu ngôi thứ ba số ít nên động từ chính về nguyên mẫu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Từ hỏi đứng ở đầu câu."},{"p":"Trợ động từ đặt ngay sau từ hỏi, trước chủ ngữ."},{"p":"Động từ chính ở dạng nguyên mẫu khi đã có do, does hoặc did."},{"p":"Bỏ trợ động từ khi từ hỏi chính là chủ ngữ."}]}],"id":"a1-17"},{"n":18,"title":"There is / There are","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Cấu trúc there is và there are dùng để nêu sự tồn tại của một đối tượng ở đâu đó. Trong cấu trúc này, there giữ vị trí chủ ngữ; động từ hòa hợp với danh từ đứng sau. Người học cũng cần phân biệt there (tồn tại), they're (= they are) và their (sở hữu)."},{"p":"Cấu trúc chính: There is + danh từ số ít | There are + danh từ số nhiều"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): There are two windows in my room. (Nêu sự tồn tại | Miêu tả một nơi | Nêu số lượng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu sự tồn tại: Giới thiệu một đối tượng mới mà người nghe chưa biết, thường kèm trạng ngữ nơi chốn. (There is a bank near here.)"},{"p":"Miêu tả một nơi: Liệt kê những gì có trong phòng, trong nhà, trong thành phố. (There are three bedrooms in the flat.)"},{"p":"Nêu số lượng: Thường đi với số từ hoặc lượng từ như some, any, a lot of. (There are some letters for you.)"},{"p":"Hỏi về sự tồn tại: Đảo động từ lên trước there để tạo câu hỏi. (Is there a lift in this building?)"},{"p":"Ghi nhớ: Dùng there is với danh từ số ít hoặc không đếm được, there are với danh từ số nhiều."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: There is + danh từ số ít | There are + danh từ số nhiều"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Khẳng định","There is / There are + danh từ (+ trạng ngữ nơi chốn)","There is a problem."],["Phủ định","There is not any … | There are not any …","There aren't any seats left."],["Nghi vấn","Is there …? | Are there …?","Are there any questions?"],["Liệt kê","động từ hòa hợp với danh từ đầu tiên","There is a desk, two chairs and a lamp."],["Quá khứ","There was + số ít/không đếm được | There were + số nhiều","There was a storm last night. / There were several discrepancies."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Tìm danh từ đứng ngay sau there is/are: Danh từ này mới là thành phần quyết định dạng động từ, không phải từ there. (There are two windows.)"},{"p":"02. Chọn is hoặc are theo danh từ: Danh từ không đếm được dù mang nghĩa khối lượng lớn vẫn đi với is. (There is some milk.)"},{"p":"03. Dùng any trong câu phủ định và nghi vấn: Some chuyển thành any khi câu không còn ở thể khẳng định. (Is there any sugar?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Số nhiều","There are two windows in my room.\n(Phòng tôi có hai cửa sổ.)","Two windows là số nhiều nên dùng there are, dù chủ ngữ hình thức vẫn là there."],["Số ít","There is a bank near the market.\n(Gần chợ có một ngân hàng.)","A bank là danh từ số ít nên dùng there is."],["Không đếm được","There is some milk in the fridge.\n(Trong tủ lạnh có một ít sữa.)","Milk không đếm được nên vẫn dùng there is."],["Phủ định","There aren't any seats left on this bus.\n(Xe buýt này không còn ghế nào.)","Câu phủ định với danh từ đếm được số nhiều dùng aren't any."],["Nghi vấn","Is there a lift in this building?\n(Toà nhà này có thang máy không?)","Câu hỏi đảo is lên trước there."],["Liệt kê","There is a desk, two chairs and a lamp in the office.\n(Trong phòng làm việc có một cái bàn, hai cái ghế và một cái đèn.)","Khi liệt kê, động từ hòa hợp với danh từ đầu tiên trong chuỗi."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Phân biệt there, their và they're"},{"table":[["Từ","Nghĩa / Chức năng","Ví dụ"],["there","ở đó hoặc chủ ngữ hình thức trong cấu trúc tồn tại","There is a shop over there."],["their","tính từ sở hữu của they","Their house is new."],["they're","dạng rút gọn của they are","They're waiting outside."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: There is two windows in my room. → Đã sửa: There are two windows in my room. — Động từ phải hòa hợp với danh từ số nhiều two windows."},{"p":"Chưa đúng: There have a bank near here. → Đã sửa: There is a bank near here. — Tiếng Việt nói “có” nên người học hay dùng have, nhưng cấu trúc tồn tại dùng there is/are."},{"p":"Chưa đúng: They're a lot of people here. → Đã sửa: There are a lot of people here. — They're nghĩa là họ đang; cấu trúc tồn tại phải là there are."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Danh từ ngay sau there là số ít, số nhiều hay không đếm được."},{"p":"Động từ is hoặc are hòa hợp với danh từ đó."},{"p":"Câu phủ định và nghi vấn dùng any thay cho some."},{"p":"There không bị viết lẫn với their hoặc they're."},{"p":"Kể chuyện quá khứ thì đổi is/are thành was/were, quy tắc chọn theo danh từ giữ nguyên."}]}],"id":"a1-18"},{"n":19,"title":"Can, could & imperatives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Can diễn tả khả năng, sự cho phép và lời đề nghị ở hiện tại; could là dạng quá khứ của can, đồng thời dùng để nói lịch sự hơn. Cả hai đều là động từ khuyết thiếu nên không chia theo chủ ngữ và luôn đi với động từ nguyên mẫu không to. Câu mệnh lệnh thì lược bỏ chủ ngữ và mở đầu ngay bằng động từ nguyên mẫu."},{"p":"Cấu trúc chính: can/could + V nguyên mẫu | V nguyên mẫu + …!"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She can swim very well. (Nói về khả năng | Xin và cho phép | Đề nghị giúp đỡ hoặc nhờ vả)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nói về khả năng: Can chỉ năng lực làm được việc gì ở hiện tại, could chỉ năng lực trong quá khứ. (She can swim. / I could read at five.)"},{"p":"Xin và cho phép: Can I…? dùng để xin phép; could lịch sự hơn can. (Can I borrow your pen? / Could I ask a question?)"},{"p":"Đề nghị giúp đỡ hoặc nhờ vả: Could you… là cách nhờ vả lịch sự thông dụng nhất. (Could you help me, please?)"},{"p":"Ra lệnh, hướng dẫn, mời: Câu mệnh lệnh dùng cho chỉ dẫn, biển báo và lời mời thân mật. (Turn left at the corner. / Please sit down.)"},{"p":"Ghi nhớ: Can và could đi với động từ nguyên mẫu không to; câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: can/could + V nguyên mẫu | V nguyên mẫu + …!"},{"table":[["Dạng câu","Công thức","Ví dụ"],["Khẳng định","S + can/could + V nguyên mẫu","He can drive."],["Phủ định","S + cannot (can't) / could not (couldn't) + V","I can't swim."],["Nghi vấn","Can/Could + S + V?","Can you help me?"],["Mệnh lệnh","V nguyên mẫu + …! | Don't + V + …!","Close the door. / Don't be late."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Giữ nguyên dạng can và could: Động từ khuyết thiếu không thêm -s ở ngôi thứ ba số ít. (She can, không phải She cans)"},{"p":"02. Dùng động từ nguyên mẫu không to: Thêm to sau can là lỗi rất phổ biến. (can swim, không phải can to swim)"},{"p":"03. Lược bỏ chủ ngữ trong câu mệnh lệnh: Câu mệnh lệnh phủ định thêm don't ở đầu; thêm please để lịch sự hơn. (Don't touch that. / Please wait here.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Khả năng hiện tại","She can swim very well.\n(Cô ấy bơi rất giỏi.)","Can giữ nguyên dạng với she và swim ở dạng nguyên mẫu không to."],["Khả năng quá khứ","I could read before I started school.\n(Tôi đã biết đọc từ trước khi đi học.)","Could là dạng quá khứ của can, dùng cho năng lực trong quá khứ."],["Xin phép","Can I borrow your pen for a minute?\n(Tôi mượn bút của bạn một chút nhé?)","Can I dùng để xin phép; đổi thành Could I sẽ lịch sự hơn."],["Nhờ vả lịch sự","Could you open the window, please?\n(Bạn mở cửa sổ giúp tôi nhé?)","Could you là mẫu nhờ vả lịch sự, không mang nghĩa quá khứ ở đây."],["Phủ định","He can't come to the party tonight.\n(Tối nay anh ấy không đến dự tiệc được.)","Dạng phủ định viết liền là cannot, rút gọn thành can't."],["Mệnh lệnh","Turn left at the traffic lights and don't cross the bridge.\n(Rẽ trái ở đèn giao thông và đừng qua cầu.)","Câu mệnh lệnh không có chủ ngữ; dạng phủ định thêm don't ở đầu."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Can và could trong các sắc thái khác nhau"},{"table":[["Cấu trúc","Sắc thái / Cách dùng","Ví dụ"],["can","khả năng hiện tại, xin phép thân mật","I can help you now."],["could","khả năng quá khứ hoặc lời nhờ vả lịch sự","Could you repeat that?"],["be able to","thay cho can ở những thì mà can không có dạng","I will be able to come tomorrow."],["May I …?","xin phép trang trọng, lịch sự hơn Can I …?","May I borrow your pen?"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She can to swim very well. → Đã sửa: She can swim very well. — Sau động từ khuyết thiếu là động từ nguyên mẫu không to."},{"p":"Chưa đúng: He cans play the piano. → Đã sửa: He can play the piano. — Động từ khuyết thiếu không thêm -s ở ngôi thứ ba số ít."},{"p":"Chưa đúng: You close the door, please. → Đã sửa: Close the door, please. — Câu mệnh lệnh lược bỏ chủ ngữ; giữ you lại sẽ thành câu kể."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Can hoặc could giữ nguyên dạng với mọi chủ ngữ."},{"p":"Động từ sau can và could ở dạng nguyên mẫu không to."},{"p":"Câu mệnh lệnh không có chủ ngữ."},{"p":"Sắc thái lịch sự đã phù hợp với tình huống."}]}],"id":"a1-19"}];
